func (q *Queries) SearchDeviceReports(ctx context.Context, arg SearchDeviceReportsParams) ([]*DeviceReport, error) {
	rows, err := q.query(ctx, q.searchDeviceReportsStmt, searchDeviceReports,
		arg.DateGTE,
		arg.DateGT,
		arg.DateEQ,
		arg.DateLTE,
		arg.DateLT,
		arg.CreatedAtGTE,
		arg.CreatedAtLTE,
		arg.CreatedAtGT,
		arg.CreatedAtLT,
		arg.UpdatedGTE,
		arg.UpdatedLTE,
		arg.UpdatedGT,
		arg.UpdatedLT,
		arg.IDEq,
		arg.IDIn,
		arg.DeviceEq,
		arg.AppEq,
		arg.IncludeDeleted,
		arg.Skip,
		arg.Limit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []*DeviceReport
	for rows.Next() {
		var i DeviceReport
		if err := rows.Scan(
			&i.ID,
			&i.DeviceBatteryPercent,
			&i.IsDeviceCharging,
			&i.PumpState,
			&i.PumpReservoir,
			&i.PumpBatteryPercent,
			&i.PumpChargingState,
			&i.LoopIob,
			&i.LoopIobBasal,
			&i.LoopIobTreatment,
			&i.LoopCob,
			&i.ConfigurationID,
			&i.LoopStatusJson,
			&i.LoopName,
			&i.PumpClock,
			&i.PumpManufacturer,
			&i.PumpModel,
			&i.OverrideJson,
			&i.PumpJson,
			&i.UploaderJson,
			&i.DeletedAt,
			&i.UtcOffsetMinutes,
			&i.OccurredAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.UpdatedByIdentityID,
			&i.UpdatedByIdentityName,
			&i.CreatedByAppName,
			&i.CreatedByDeviceName,
			&i.CreatedByIdentityID,
			&i.CreatedByIdentityName,
		); err != nil {
			return nil, err
		}
		items = append(items, &i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const softDeleteDeviceReport = `-- name: SoftDeleteDeviceReport :execresult

UPDATE device_reports SET
    deleted_at = CAST(unixepoch('subsec') * 1000 AS INTEGER),
    updated_at = MAX(updated_at + 1, CAST(unixepoch('subsec') * 1000 AS INTEGER)),
    updated_by_identity_name = ?1
WHERE id = ?2 AND deleted_at IS NULL
`

type SoftDeleteDeviceReportParams struct {
	UpdatedByIdentityName *string
	ID                    string
}

// ------
// DELETE
// ------
func (q *Queries) SoftDeleteDeviceReport(ctx context.Context, arg SoftDeleteDeviceReportParams) (sql.Result, error) {
	return q.exec(ctx, q.softDeleteDeviceReportStmt, softDeleteDeviceReport, arg.UpdatedByIdentityName, arg.ID)
}

